package sohal.lld.snakeladder.board.builder;import sohal.lld.snakeladder.board.Board;import sohal.lld.snakeladder.dice.Dice;import sohal.lld.snakeladder.entity.Entity;import sohal.lld.snakeladder.entity.factory.EntityFactory;import sohal.lld.snakeladder.entity.factory.LadderFactory;import sohal.lld.snakeladder.entity.factory.SnakeFactory;import java.util.HashMap;import java.util.HashSet;import java.util.Map;import java.util.Set;public class BoardBuilder {    private int size=100;    private int snakeCount=10;    private int ladderCount=10;    private EntityFactory snakeFactory;    private EntityFactory ladderFactory;    private final Set<Integer> usedPositions = new HashSet<>();    private final Map<Integer, Entity> entities = new HashMap<>();    public BoardBuilder() {    }    public static BoardBuilder newBuilder() {        return new BoardBuilder();    }    public BoardBuilder withSize(int size) {        this.size = size;        return this;    }    public BoardBuilder withSnakes(int snakeCount) {        this.snakeCount = snakeCount;        return this;    }    public BoardBuilder withLadders(int ladderCount) {        this.ladderCount = ladderCount;        return this;    }    public BoardBuilder withSnakeFactory(SnakeFactory snakeFactory) {        this.snakeFactory = snakeFactory;        return this;    }    public BoardBuilder withLadderFactory(LadderFactory ladderFactory) {        this.ladderFactory = ladderFactory;        return this;    }    private void validate() {        if(snakeFactory==null) {            throw new IllegalArgumentException("snakeFactory is null");        }        if(ladderFactory==null) {            throw new IllegalArgumentException("snakeFactory,ladderFactory is null");        }        if(size<=0) {            throw new IllegalArgumentException("size <= 0");        }    }    private void generateSnakes() {        int i = snakeCount;        while (i > 0) {            Entity snake = snakeFactory.createEntity(usedPositions);            entities.put(snake.getStart(), snake);            i--;        }    }    private void generateLadders() {        int j = ladderCount;        while (j > 0) {            Entity ladder = ladderFactory.createEntity(usedPositions);            entities.put(ladder.getStart(), ladder);            j--;        }    }    public Board build() {        validate();        generateSnakes();        generateLadders();        return new Board(size, entities);    }}